        //   getPrice('NSE:A', 'close')                                 — single, chart tf
        //   getPrice('NSE:A', 'close', { timeframe: '5' })             — single, custom tf
        //   getPrice([s1, s2], 'close')                                — array, chart tf
        //   getPrice([{symbol:'A', timeframe:'5'}, ...], 'close')      — array, mixed tf
        //   getPrice({a:'A', b:'B'}, 'close')                          — object, chart tf
        //   getPrice({a:{symbol:'A', timeframe:'5'}, b:'B'}, 'close')  — object, mixed tf
