            // so the symId joins symbolsMap (live ticks) and pendingSymbolFetch
            // gates double-sends. Sending a 1-item ohlc_batch is fine — server
            // accepts it and the response handler is shared.
            if (callerTf && callerTf !== this.timeframe && symbol) {
                sysfunc.registerSymbolsBatch(this, [{ symbol, timeframe: callerTf }]);
            }
            const result = await sysfunc.getPrice(ptype, dataName, this, symbol, type, callerTf);
            this._priceCache[cacheKey] = result;
